    /**
     * Method to retrieve the Lead via LeadFetchOneSummary
     * @param 	summary LeadFetchOneSummary 
     * @return 	LeadFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Lead getLead( LeadFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "LeadFetchOneSummary arg cannot be null" );
    	
    	Lead entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Lead
        	// --------------------------------------
        	CompletableFuture<Lead> futureEntity = queryGateway.query(new FindLeadQuery( new LoadLeadFilter( summary.getLeadId() ) ), ResponseTypes.instanceOf(Lead.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Lead with id " + summary.getLeadId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


